CREATE VIEW std_game_resource_candidates AS WITH resource_raw AS ((SELECT main."trim"(Title) AS game_title, 'MapGenie' AS resource_type, CASE  WHEN ((main."trim"(CAST("MapGenie?" AS VARCHAR)) = 'Y')) THEN (CAST('t' AS BOOLEAN)) WHEN ((main."trim"(CAST("MapGenie?" AS VARCHAR)) = 'N')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END AS available_flag FROM stg_ps4_inventory) UNION ALL (((SELECT main."trim"(Title), 'MapGenie', CAST("MapGenie?" AS BOOLEAN) FROM stg_ps5_inventory) UNION ALL (SELECT main."trim"(Title), 'SaveWizard', CASE  WHEN ((main."trim"(CAST("Save Wizard?" AS VARCHAR)) = 'Y')) THEN (CAST('t' AS BOOLEAN)) WHEN ((main."trim"(CAST("Save Wizard?" AS VARCHAR)) = 'N')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END FROM stg_ps4_inventory)) UNION ALL (SELECT main."trim"(Title), 'Mods', CASE  WHEN ((main."trim"(CAST("Mods?" AS VARCHAR)) = 'Y')) THEN (CAST('t' AS BOOLEAN)) WHEN ((main."trim"(CAST("Mods?" AS VARCHAR)) = 'N')) THEN (CAST('f' AS BOOLEAN)) ELSE NULL END FROM stg_wiiu_inventory))), resolved AS (SELECT game_title, resource_type, count(DISTINCT available_flag) FILTER (WHERE (available_flag IS NOT NULL)) AS distinct_flag_values, max(available_flag) AS available_flag FROM resource_raw GROUP BY game_title, resource_type)SELECT g.GameID, r.ResourceTypeID, x.available_flag FROM resolved AS x INNER JOIN Game AS g ON ((g.GameTitle = x.game_title)) INNER JOIN ResourceType AS r ON ((r.ResourceTypeName = x.resource_type)) WHERE ((x.distinct_flag_values = 1) AND (x.available_flag IS NOT NULL));
